    static void Escape(EditorFrame* page){services::NeutralTestKeys();MSG m{};m.hwnd=page->m_hWnd;m.message=WM_KEYDOWN;m.wParam=VK_ESCAPE;page->PreTranslateMessage(&m);}
    static core::Image Paint(EditorFrame* page){
        CRect client;page->GetClientRect(client);CClientDC screen(page);CDC dc;dc.CreateCompatibleDC(&screen);BITMAPINFO info{};info.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);info.bmiHeader.biWidth=client.Width();info.bmiHeader.biHeight=-client.Height();info.bmiHeader.biPlanes=1;info.bmiHeader.biBitCount=32;void* pixels=nullptr;
        HBITMAP bitmap=CreateDIBSection(screen,&info,DIB_RGB_COLORS,&pixels,nullptr,0);if(!bitmap)return {};auto old=::SelectObject(dc,bitmap);dc.FillSolidRect(client,RGB(249,250,251));page->PaintContent(dc);GdiFlush();core::Image image;image.Create(client.Width(),client.Height());memcpy(image.pixels.data(),pixels,image.pixels.size());for(size_t i=3;i<image.pixels.size();i+=4)image.pixels[i]=255;::SelectObject(dc,old);::DeleteObject(bitmap);return image;
    }
    static void SaveEvidence(EditorFrame* page,const std::filesystem::path& path,Check check){auto image=Paint(page);CString error;std::vector<BYTE> bytes;check(services::EncodeImage(image,L"png",100,bytes,error)&&services::WriteBytes(path.c_str(),bytes,error),"hidden canvas paint evidence saved without desktop capture or foreground activation");}
    static core::Image Source(){core::Image image;image.Create(320,220);for(int y=0;y<220;++y)for(int x=0;x<320;++x){auto* p=image.Row(y)+x*4;p[0]=static_cast<BYTE>(x%200);p[1]=static_cast<BYTE>(y%200);p[2]=80;p[3]=x<10?0:255;}return image;}
    static bool ColorAt(const core::Image& image,CPoint p,COLORREF color){if(p.x<0||p.y<0||p.x>=image.width||p.y>=image.height)return false;const auto* pixel=image.Row(p.y)+p.x*4;return pixel[0]==GetBValue(color)&&pixel[1]==GetGValue(color)&&pixel[2]==GetRValue(color);}
    static bool FramePixels(const core::Image& image,CRect content,int border){
        CRect outer=content;outer.InflateRect(border,border);const CRect strips[]={{outer.left,outer.top,outer.right,content.top},{outer.left,content.bottom,outer.right,outer.bottom},{outer.left,content.top,content.left,content.bottom},{content.right,content.top,outer.right,content.bottom}};
        for(const auto& strip:strips)for(int y=strip.top;y<strip.bottom;++y)for(int x=strip.left;x<strip.right;++x)if(!ColorAt(image,{x,y},RGB(136,146,158)))return false;
        return true;
    }
